"""Underline all headline paragraphs in the unpacked quarterly_report.docx.

Headlines are recognized structurally from the document's actual content:
every paragraph in this report has an empty <w:pPr/> (no heading styles),
and the headlines are the only non-empty paragraphs whose full text is
uppercase-only (e.g., "EXECUTIVE SUMMARY").  Body text, bullets, and table
rows all contain lowercase text, so this detection is unambiguous for this
document.

For each headline paragraph we add <w:u w:val="single"/> into each run's
<w:rPr> (inserted at the schema-correct position, after szCs/highlight and
before any later rPr child), leaving all other content untouched.
"""

import sys

try:
    from defusedxml import minidom
except ImportError:  # pragma: no cover - fallback for minimal environments
    from xml.dom import minidom

W = "http://schemas.openxmlformats.org/wordprocessingml/2006/main"
DOC = "unpacked/word/document.xml"

# CT_RPr child order (ECMA-376) -- w:u sits after szCs/highlight.
_RPR_ORDER = [
    "w:rStyle", "w:rFonts", "w:b", "w:bCs", "w:i", "w:iCs", "w:caps",
    "w:smallCaps", "w:strike", "w:dstrike", "w:outline", "w:shadow",
    "w:emboss", "w:imprint", "w:noProof", "w:snapToGrid", "w:vanish",
    "w:webHidden", "w:color", "w:spacing", "w:w", "w:kern", "w:position",
    "w:sz", "w:szCs", "w:highlight", "w:u", "w:effect", "w:bdr", "w:shd",
    "w:fitText", "w:vertAlign", "w:rtl", "w:cs", "w:em", "w:lang",
    "w:eastAsianLayout", "w:specVanish", "w:oMath",
]


def para_text(p):
    parts = []
    for t in p.getElementsByTagName("w:t"):
        for node in t.childNodes:
            if node.nodeType == node.TEXT_NODE:
                parts.append(node.data)
    return "".join(parts)


def is_headline(text):
    s = text.strip()
    if not s:
        return False
    # all-caps text: at least one cased char, and every cased char uppercase.
    return text.isupper() and any(ch.isalpha() for ch in s)


def add_underline_to_run(doc, run):
    # find/create rPr as first child of run (schema requires it first)
    rpr = None
    for child in run.childNodes:
        if child.nodeType == child.ELEMENT_NODE and child.tagName == "w:rPr":
            rpr = child
            break
    if rpr is None:
        rpr = doc.createElement("w:rPr")
        run.insertBefore(rpr, run.firstChild)

    # skip if underline already set
    for child in rpr.childNodes:
        if child.nodeType == child.ELEMENT_NODE and child.tagName == "w:u":
            return False

    u = doc.createElement("w:u")
    u.setAttribute("w:val", "single")

    # insert at schema-correct position
    anchor = None
    for child in rpr.childNodes:
        if child.nodeType != child.ELEMENT_NODE:
            continue
        if child.tagName in _RPR_ORDER and _RPR_ORDER.index(child.tagName) > _RPR_ORDER.index("w:u"):
            anchor = child
            break
    if anchor is not None:
        rpr.insertBefore(u, anchor)
    else:
        rpr.appendChild(u)
    return True


def main():
    dom = minidom.parse(DOC)
    body = dom.getElementsByTagName("w:body")[0]

    headlines = []
    for p in body.getElementsByTagName("w:p"):
        text = para_text(p)
        if is_headline(text):
            headlines.append(text)
            for run in p.getElementsByTagName("w:r"):
                add_underline_to_run(dom, run)

    if not headlines:
        print("ERROR: no headlines detected; document left unchanged")
        sys.exit(1)

    with open(DOC, "wb") as fh:
        fh.write(dom.toprettyxml(indent="  ", newl="\n", encoding="ascii"))

    print("Underlined %d headline(s):" % len(headlines))
    for h in headlines:
        print("  - " + h.strip())


if __name__ == "__main__":
    main()

