#!/usr/bin/env python3
"""Underline all headline paragraphs in the unpacked quarterly report docx.

Headlines are detected structurally from word/document.xml: a paragraph whose
XML-unescaped text is non-empty, contains no lowercase letters, and contains at
least one letter.  Underline formatting (<w:u w:val="single"/>) is ensured inside
the run properties of every text run of each headline paragraph.  The operation
is idempotent and preserves the existing pretty-printed XML layout.
"""
import html
import os

DOC = os.path.join("unpacked", "word", "document.xml")


def line_text(line):
    """Return the text content of a <w:t> element line, or None."""
    s = line.strip()
    if not s.startswith("<w:t"):
        return None
    if s.endswith("/>"):
        return ""  # e.g. <w:t xml:space="preserve"/>
    if s.endswith("</w:t>"):
        start = s.find(">")
        if start != -1:
            return html.unescape(s[start + 1:-len("</w:t>")])
    return None


def is_headline(plain):
    if not plain:
        return False
    letters = [ch for ch in plain if ch.isalpha()]
    if not letters:
        return False
    return not any(ch.islower() for ch in plain)


def whitespace(line):
    return line[:len(line) - len(line.lstrip())]


def find_paragraphs(lines):
    paras = []
    start = None
    texts = []
    for idx, ln in enumerate(lines):
        s = ln.strip()
        if s == "<w:p>" or s.startswith("<w:p "):
            start = idx
            texts = []
        if start is not None:
            c = line_text(ln)
            if c is not None:
                texts.append((idx, c))
        if s == "</w:p>" and start is not None:
            paras.append({"start": start, "end": idx, "texts": texts})
            start = None
    return paras


def ensure_run_underline(lines, para, text_idx, edits):
    """Collect an edit (index, lines-to-insert) if this run lacks underline."""
    ti = text_idx
    run_i = None
    for j in range(ti - 1, para["start"], -1):
        s = lines[j].strip()
        if s == "<w:r>" or s.startswith("<w:r "):
            run_i = j
            break
    if run_i is None:
        return
    open_i = None
    close_i = None
    self_close = False
    for j in range(run_i + 1, ti):
        s = lines[j].strip()
        if s == "<w:rPr/>":
            open_i = j
            self_close = True
            break
        if s == "<w:rPr>" or s.startswith("<w:rPr "):
            open_i = j
            break
    if open_i is None:
        # No run properties at all: add a new rPr block before the text.
        prefix = whitespace(lines[run_i])
        edits.append((ti, [
            prefix + "  <w:rPr>",
            prefix + "    <w:u w:val=\"single\"/>",
            prefix + "  </w:rPr>",
        ]))
        return
    if self_close:
        # <w:rPr/> has no children, so it cannot contain an underline yet.
        prefix = whitespace(lines[open_i])
        edits.append((open_i, [
            prefix + "<w:rPr>",
            prefix + "  <w:u w:val=\"single\"/>",
            prefix + "</w:rPr>",
        ]))
        return
    if close_i is None:
        for j in range(open_i + 1, ti):
            if lines[j].strip() == "</w:rPr>":
                close_i = j
                break
    if close_i is None:
        return  # malformed; leave untouched
    if any("<w:u" in lines[k] for k in range(open_i, close_i + 1)):
        return  # already underlined
    prefix = whitespace(lines[open_i])
    edits.append((close_i, [prefix + "  <w:u w:val=\"single\"/>"]))


with open(DOC, encoding="utf-8") as fh:
    raw = fh.read()
lines = raw.split("\n")

paras = find_paragraphs(lines)
edits = []
headlines = []

for para in paras:
    plain = "".join(text for _idx, text in para["texts"])
    if not is_headline(plain):
        continue
    headlines.append((para, plain.strip()))
    for ti, _text in para["texts"]:
        ensure_run_underline(lines, para, ti, edits)

# Apply edits bottom-up so earlier indices stay valid.
edits.sort(key=lambda e: e[0], reverse=True)
for idx, new_lines in edits:
    lines[idx:idx] = new_lines

result = "\n".join(lines)
with open(DOC, "w", encoding="utf-8") as fh:
    fh.write(result)

# Verification pass: confirm each headline run now has an underline element.
verified = []
for para, plain in headlines:
    ok_runs = 0
    for ti, _text in para["texts"]:
        run_ok = False
        for j in range(ti - 1, para["start"], -1):
            s = lines[j].strip()
            if s == "<w:r>" or s.startswith("<w:r "):
                break
            if "<w:u" in lines[j]:
                run_ok = True
                break
        if run_ok:
            ok_runs += 1
    verified.append(ok_runs == len(para["texts"]) and len(para["texts"]) > 0)

for (para, plain), ok in zip(headlines, verified):
    status = "OK" if ok else "MISSING UNDERLINE"
    print("HEADLINE: %-40s -> %s" % (plain[:40], status))

print("headlines=%d underlined=%d edits_applied=%d" % (
    len(headlines), sum(verified), len(edits)))
if not headlines or not all(verified):
    raise SystemExit("verification failed: not all headlines underlined")
print("saved %s" % DOC)

